        Class<?> modelType=Arrays.stream(ProjectManagedRunnerJourneyTest.class.getDeclaredClasses()).filter(c->c.getSimpleName().equals("FixtureModel")).findFirst().orElseThrow();Constructor<?> constructor=modelType.getDeclaredConstructor(ProjectManagedRunnerJourneyTest.class,boolean.class,boolean.class);constructor.setAccessible(true);Object model=constructor.newInstance(original,false,true);
        try(AutoCloseable ignored=(AutoCloseable)model){call("runWithOwnerApprovals",new Class<?>[]{modelType},model);for(String name:List.of("sawActualFailure","sawActualDependency","sawActualTests","finished")){Field f=modelType.getDeclaredField(name);f.setAccessible(true);assertTrue(name,f.getBoolean(model));}assertTrue(Files.readString(root(checkout).resolve("src/main.js")).contains("继续同一个项目"));assertTrue(Files.readString(root(checkout).resolve("dist/index.html")).contains("<script"));assertArrayEquals(new byte[]{0,1,-1,42},Files.readAllBytes(root(checkout).resolve("raw.bin")));assertTrue(Files.isDirectory(root(checkout).resolve("empty")));AtomicReference<Exception> failures=field("callbackFailure");assertNull(failures.get());assertFalse(tasks.hasUnresolved(task));
            JSONObject chosen=local.handle("project.package.plan",new JSONObject().put("checkoutId",checkout).put("mode","source_project").put("entryPath","").put("includeGeneratedRoots",true));JSONObject saved=local.handle("project.package.freeze",new JSONObject().put("checkoutId",checkout).put("mode","source_project").put("entryPath","").put("includeGeneratedRoots",true).put("expectedSourceDigest",chosen.getString("sourceDigest")).put("expectedManifestIdentity",chosen.getString("manifestIdentity")).put("clientSnapshotId",UUID.randomUUID().toString()));JSONObject preview=local.handle("project.package.preview",new JSONObject().put("artifactId",saved.getString("id")).put("sha256",saved.getString("sha256")).put("entryPath","dist/index.html"));ProjectPreviewBundle.Verified frozen=local.projectPreviewForOwner(preview.getString("previewId"),checkout);assertEquals(4,frozen.manifest().length());assertEquals(saved.getString("sha256"),frozen.artifactSha256);
            System.out.println("NEW_C03_RUNNER ordinary ZIP actual source -> new empty checkout -> explicitly start original task/owner approvals -> real host JNI official locked npm/esbuild -> actual nonzero missing-view stderr in same model history -> approved SHA-CAS repair -> tests/build/two real previews -> same-project continue -> original owner package freeze/four-resource immutable preview. Model HTTP fixture; legacy small-plan protocol here, new-run planRef proved separately by new F010. Android SAF/ARM/DOM/provider not verified.");}
